pub fn load(path: &str) -> Meta {
    let b = fs::read(path).unwrap_or_default();
    if b.len() < 12 || &b[0..4] != b"CLAT" {
        return Meta {
            write_stamp: 0,
            crash: None,
            guid: [0; 16],
            companion: 0,
        };
    }
    let write_stamp = u32::from_le_bytes(b[6..10].try_into().unwrap());
    let n = u16::from_le_bytes(b[10..12].try_into().unwrap()) as usize;
    let mut crash = None;
